const panel = document.querySelector('.xp-workshop-widget:last-child .xp-workshop-content');
if (!panel) throw Error('Console panel unavailable');
const button = document.createElement('button');
button.className = 'mini-action';
button.textContent = 'Fetch device status';
const output = document.createElement('pre');
output.style.cssText = 'white-space:pre-wrap;overflow-wrap:anywhere;color:#ff8fda';
output.textContent = 'Click to query the ESP32';
panel.append(button, output);
let enabled = true;
button.onclick = async () => {
  if (!enabled) return;
  button.disabled = true;
  try {
    const data = await xlink.status();
    if (enabled) output.textContent = JSON.stringify(data, null, 2);
    xlink.log('Device status fetched by Console plugin');
  } catch (e) { if (enabled) output.textContent = 'Error: ' + e.message; }
  finally { button.disabled = false; }
};
return () => { enabled = false; button.onclick = null; };
